?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add Money - Games Club BD</title><link href="https://fonts.googleapis.com/css2?family=Lato:wght@400;700;900&family=Hind+Siliguri:wght@400;600;700&display=swap" rel="stylesheet"><style>*{box-sizing:border-box}body{margin:0;background:#f5f6fa;font-family:Lato,'Hind Siliguri',sans-serif;color:#222}.bar{background:white;padding:16px;border-bottom:1px solid #eee;font-weight:900}.bar a{color:#222;text-decoration:none}.wrap{max-width:500px;margin:22px auto;padding:0 15px}.card{background:white;border-radius:14px;padding:22px;box-shadow:0 4px 16px #0000000b}.card h1{font-size:21px;margin:0 0 7px}.muted{color:#687080;font-size:14px}.brand{display:inline-flex;align-items:center;gap:8px;background:#eef5ff;color:#1976d2;font-weight:800;padding:8px 11px;border-radius:20px;margin:14px 0}.amount{width:100%;padding:14px;border:1px solid #d6dbe2;border-radius:8px;font-size:17px;margin:8px 0 16px}.pay{width:100%;padding:14px;border:0;border-radius:8px;background:#1976d2;color:white;font-size:16px;font-weight:900;cursor:pointer}.pay:disabled{opacity:.6;cursor:wait}.notice{padding:12px;border-radius:8px;margin:12px 0;background:#eef5ff;color:#164781}.notice.error{background:#fff0f0;color:#a21c1c}.notice.success{background:#e8f7ed;color:#17632d}</style></head><body><header class="bar"><a href="index.php">← &nbsp; My Wallet</a></header><main class="wrap"><section class="card"><h1>Instant Add Money (Goriber Pay)</h1><p class="muted">Enter the amount to add to your Games Club BD wallet. You will be redirected to Goriber Pay to complete the payment.</p><div class="brand">● &nbsp; Goriber Pay</div><form id="payment-form"><input type="hidden" id="csrf" value="<?= h($csrf) ?>"><label class="muted" for="amount">Amount (BDT)</label><input class="amount" id="amount" name="amount" type="number" min="1" max="1000000" step="0.01" placeholder="Enter amount" required><button class="pay" id="pay-button" type="submit">PAY NOW</button></form><div id="payment-message" class="notice" role="status" <?= $transactionId ? '' : 'hidden' ?>></div></section></main><script>const csrf=document.getElementById('csrf').value;const message=document.getElementById('payment-message');async function verifyPayment(id){message.hidden=false;message.textContent='Verifying payment with Goriber Pay…';try{const r=await fetch('api/verify_payment.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({transactionId:id})});const d=await r.json();message.textContent=d.message||d.error||'Unable to verify payment.';message.className='notice '+(d.ok?'success':'error')}catch(_){message.textContent='Could not verify payment. Please reload and try again.';message.className='notice error'}}const transactionId=<?= json_encode($transactionId) ?>;if(transactionId)verifyPayment(transactionId);document.getElementById('payment-form').addEventListener('submit',async e=>{e.preventDefault();const button=document.getElementById('pay-button');button.disabled=true;button.textContent='PLEASE WAIT…';message.hidden=false;message.className='notice';message.textContent='Connecting to Goriber Pay…';try{const r=await fetch('api/create_payment.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({amount:document.getElementById('amount').value})});const d=await r.json();if(!d.ok)throw new Error(d.error||'Could not start payment.');location.href=d.payment_url}catch(err){message.className='notice error';message.textContent=err.message;button.disabled=false;button.textContent='PAY NOW'}});</script></body></html>
